svg.script:

let isSmiling = false;
const mouth = document.getElementById('mouth');

mouth.addEventListener('click', function() {
  if (!isSmiling) {
    // Change to smile
    mouth.setAttribute('d', 'M 56.5 69 Q 60 71.5 63.5 69');
    isSmiling = true;
  } else {
    // Change back to flat
    mouth.setAttribute('d', 'M 58 70 L 62 70');
    isSmiling = false;
  }
});
